  1626→                BlockProcessingError::BeaconStateError(e) => return Err(e.into()),
  1627→                other => return Err(BlockError::PerBlockProcessingError(other)),
  1628→            }
  1629→        };
  1630→
  1631→        metrics::stop_timer(core_timer);
  1632→
  1633→        /*
  1634→         * Calculate the state root of the newly modified state
  1635→         */
