  1643→        write_state(&format!("state_post_block_{}", block_root), &state);
  1644→
  1645→        /*
  1646→         * Check to ensure the state root on the block matches the one we have calculated.
  1647→         */
  1648→
  1649→        if block.state_root() != state_root {
  1650→            return Err(BlockError::StateRootMismatch {
  1651→                block: block.state_root(),
  1652→                local: state_root,
  1653→            });
  1654→        }
  1655→
  1656→        /*
  1657→         * Apply the block's attestations to fork choice.
  1658→         *
  1659→         * We're running in parallel with the payload verification at this point, so this is
  1660→         * free real estate.
  1661→         */
  1662→        let current_slot = chain.slot()?;
  1663→        let mut fork_choice = chain.canonical_head.fork_choice_write_lock();
  1664→
  1665→        // Register each attester slashing in the block with fork choice.
  1666→        for attester_slashing in block.message().body().attester_slashings() {
